import{state,setState}from"./state.js";import{searchUsers,addFriend,loadFriendsList,updateNickname}from"./api.js";import{showToast}from"./utils.js";import{renderFriends,updateChildNicknameUI}from"./ui.js";export async function handleSearch(){const e=document.getElementById("friend-search-input"),s=document.getElementById("search-results"),t=e.value.trim();if(t.length<3)return void showToast("Ник должен быть не короче 3 символов","error");s.innerHTML='<div class="empty-state">Поиск...</div>';const n=await searchUsers(t);0!==n.length?s.innerHTML=n.map(e=>`\n        <div class="search-results-item">\n            <span>${e.nickname}</span>\n            <button class="btn btn--success btn--small" onclick="window.app.addNewFriend('${e.id}')">Добавить</button>\n        </div>\n    `).join(""):s.innerHTML='<div class="empty-state">Пользователи не найдены</div>'}export async function addNewFriend(e){const s=await addFriend(e);s.success?(showToast("Друг добавлен!","success"),await refreshFriends()):showToast(s.error||"Ошибка при добавлении","error")}export async function refreshFriends(){const e=await loadFriendsList();setState({friends:e}),renderFriends()}export async function saveNickname(){const e=document.getElementById("settings-nickname").value.trim();if(e.length<3)return void showToast("Ник должен быть не короче 3 символов","error");const s=await updateNickname(e);s.success?(showToast("Ник сохранен!","success"),setState({childNickname:e}),updateChildNicknameUI()):showToast(s.error||"Ошибка при сохранении","error")}